#!/usr/bin/env python3
"""Custom HTML-to-PPTX converter that scrolls to each slide explicitly."""

import http.server
import os
import subprocess
import sys
import tempfile
import threading
from pathlib import Path

from PIL import Image
from pptx import Presentation
from pptx.util import Emu


def main():
    html_path = Path("/app/output/skillclaw_presentation.html").resolve()
    output_path = Path("/app/output/final_deck.pptx").resolve()

    # Start HTTP server
    serve_dir = html_path.parent
    handler = http.server.SimpleHTTPRequestHandler
    server = http.server.HTTPServer(
        ("127.0.0.1", 0),
        lambda *a, **kw: handler(*a, directory=str(serve_dir), **kw),
    )
    port = server.server_address[1]
    thread = threading.Thread(target=server.serve_forever, daemon=True)
    thread.start()

    url = f"http://127.0.0.1:{port}/{html_path.name}"

    with tempfile.TemporaryDirectory(prefix="slides_") as tmp:
        tmp_dir = Path(tmp)

        # Write a Playwright script that scrolls to each .slide element directly
        script = f"""\
const {{ chromium }} = require('playwright');

(async () => {{
    const browser = await chromium.launch({{
        executablePath: process.env.PLAYWRIGHT_CHROMIUM_EXECUTABLE_PATH || undefined
    }});
    const page = await browser.newPage();
    await page.setViewportSize({{ width: 1920, height: 1080 }});
    await page.goto('{url}', {{ waitUntil: 'networkidle' }});

    // Wait for fonts and initial render
    await page.waitForTimeout(2000);

    // Count slides
    const slideCount = await page.$$eval('.slide', els => els.length);
    console.log('Found ' + slideCount + ' slides');

    // Screenshot each slide by scrolling it into view
    for (let i = 0; i < slideCount; i++) {{
        // Scroll the i-th slide into view
        await page.evaluate((idx) => {{
            const slides = document.querySelectorAll('.slide');
            slides[idx].scrollIntoView({{ behavior: 'instant' }});
        }}, i);

        // Wait for scroll and animations to settle
        await page.waitForTimeout(800);

        // Force add visible class to trigger animations
        await page.evaluate((idx) => {{
            const slides = document.querySelectorAll('.slide');
            slides[idx].classList.add('visible');
        }}, i);

        await page.waitForTimeout(500);

        const idx = String(i + 1).padStart(3, '0');
        const path = '{tmp_dir}/slide_' + idx + '.png';
        await page.screenshot({{ path }});
        console.log('Captured slide ' + (i + 1));
    }}

    await browser.close();
}})();
"""
        script_file = tmp_dir / "_capture.cjs"
        script_file.write_text(script)

        env = os.environ.copy()
        env.setdefault("PLAYWRIGHT_CHROMIUM_EXECUTABLE_PATH", "/root/.cache/ms-playwright/chromium-1155/chrome-linux/chrome")
        env.setdefault("NODE_PATH", "/usr/local/lib/node_modules:/app/node_modules")

        result = subprocess.run(
            ["node", str(script_file)],
            capture_output=True,
            text=True,
            timeout=180,
            env=env,
        )

        print("STDOUT:", result.stdout)
        if result.stderr:
            print("STDERR:", result.stderr[-500:] if len(result.stderr) > 500 else result.stderr)

        if result.returncode != 0:
            print(f"Script failed (exit {result.returncode})")
            sys.exit(1)

        server.shutdown()

        # Collect all slide images
        pngs = sorted(tmp_dir.glob("slide_*.png"))
        print(f"Found {len(pngs)} slide images")

        if not pngs:
            print("ERROR: No slide images produced")
            sys.exit(1)

        # Assemble PPTX
        prs = Presentation()
        prs.slide_width = Emu(12192000)  # 13.333 inches
        prs.slide_height = Emu(6858000)  # 7.5 inches
        blank_layout = prs.slide_layouts[6]

        for img_path in pngs:
            slide = prs.slides.add_slide(blank_layout)
            slide.shapes.add_picture(
                str(img_path),
                left=Emu(0),
                top=Emu(0),
                width=prs.slide_width,
                height=prs.slide_height,
            )

        prs.save(str(output_path))
        print(f"Done -> {output_path}")


if __name__ == "__main__":
    main()

